item.command:
/bin/bash -lc "python - <<'PY'
from pathlib import Path
for path in [Path('/workspace/galaxy_outputs/full_deseq2.tsv'),Path('/workspace/galaxy_outputs/no_rep3_deseq2.tsv')]:
    counts={'raw_total':0,'raw_up':0,'raw_down':0,'adj_total':0,'adj_up':0,'adj_down':0,'rows':0,'na':0}
    with path.open() as f:
        for line in f:
            parts=line.rstrip('\\n').split('\\t')
            counts['rows']+=1
            if len(parts)<6 or parts[1] in ('NA','') or parts[2] in ('NA',''):
                counts['na']+=1; continue
            base=float(parts[1]); lfc=float(parts[2])
            if parts[4] not in ('NA','') and float(parts[4])<0.05 and abs(lfc)>1 and base>10:
                counts['raw_total']+=1
                counts['raw_up' if lfc>0 else 'raw_down']+=1
            if parts[5] not in ('NA','') and float(parts[5])<0.05 and abs(lfc)>1 and base>10:
                counts['adj_total']+=1
                counts['adj_up' if lfc>0 else 'adj_down']+=1
    print(path.name,counts)
PY"

